SELECT ?sensor ?ts_id WHERE {
  ?zone brick:hasName "Perimeter_mid_ZN_4" .
  ?sensor brick:isPointOf ?zone .
  ?sensor rdf:type brick:Electric_Power_Sensor .
  ?sensor ref:hasTimeseriesId ?ts_id .
}

SELECT ?zone ?sensor ?ts_id WHERE {
  ?zone brick:hasName "Perimeter_mid_ZN_4" .
  ?sensor brick:isPointOf ?zone .
  OPTIONAL { ?sensor ref:hasTimeseriesId ?ts_id . }
}

SELECT ?sensor ?ts_id WHERE {
  ?sensor brick:isPointOf <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z05> .
